D2_CONNECTOR_AND_MAPPING.example:
// packages/connectors: one file per kind
export interface Connector<C> {
  kind: string;                 // "rss" | "wordpress" | "cxml" …
  configSchema: ZodType<C>;
  discover(cfg: C, since: Date): AsyncIterable<Ref>;
  fetch(cfg: C, ref: Ref): Promise<RawItem>;
}
type RawItem = { ref: Ref; format: "json" | "xml" | "html";
                 data: unknown; fetchedAt: string };
normalize(raw: RawItem, mapping: Mapping): Article  // then zod

// PUSH door
POST /v1/ingest/articles
X-Api-Key: <source key>    X-Signature: sha256=<hmac of body>
body: an Article without our ids, or {"raw": …} to run the mapping

// sources row for a WordPress site: config + mapping
{ "kind": "wordpress",
  "config": { "base": "https://site.com", "poll": "*/5 * * * *" },
  "mapping": {
    "external_id":   "$.id | prefix('wp:')",
    "url":           "$.link",
    "headline":      "$.title.rendered | strip_html",
    "subhead":       "$.excerpt.rendered | strip_html",
    "body":          "$.content.rendered | html_to_blocks",
    "section":       "$._embedded['wp:term'][0][0].slug | map(sections)",
    "images[0].src": "$._embedded['wp:featuredmedia'][0].source_url",
    "published_at":  "$.date_gmt | parse_date('UTC')" } }

// a site with no feed and no API
{ "kind": "scrape",
  "config": { "list": ["https://site.com/world/"],
              "link_selector": "article a.title",
              "obey_robots": true },
  "mapping": {
    "headline":      "css:h1.entry-title",
    "body":          "css:div.entry-content p | blocks",
    "images[0].src": "css:meta[property='og:image']@content",
    "published_at":  "jsonld:datePublished" } }

// Typefi ContentXML needs no mapping: kind "cxml" is built in

D6_HOOKS_AND_EMBED.example:
// webhook we send to the site
POST https://site.com/hooks/epaper
X-Epaper-Signature: sha256=<hmac of body>
X-Epaper-Delivery: <uuid>              // reject repeats
{ "event": "edition.published", "paper": "slug",
  "edition": "2026-11-18", "pages": 16,
  "url": "https://epaper.site.com/2026-11-18/1" }

// reader inside any page
<div data-epaper></div>
<script src="https://HOST/embed.js"
        data-paper="slug" data-edition="latest"></script>

// subscriber hand-off: site signs, reader verifies
https://epaper.site.com/latest?token=<JWT, 5 min, {sub, plan}>

// the site's receiver, in any language
valid = hmac_sha256(secret, raw_body) == signature
        and delivery_id not seen before
